import { test, expect } from '@playwright/test';

test.describe('Checkout Flow - Sequential Async Steps', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should complete checkout flow in order with sequential async steps', async ({ page }) => {
    // Step 1: Add item to cart
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    await addToCartButton.click();
    const cartCount = page.getByText('Cart Items: 1');
    await expect(cartCount).toBeVisible();

    // Step 2: Proceed to checkout
    const checkoutButton = page.getByRole('button', { name: /proceed to checkout/i });
    await checkoutButton.click();
    const checkoutForm = page.getByRole('form', { name: /checkout/i });
    await expect(checkoutForm).toBeVisible();

    // Step 3: Enter shipping address
    const shippingAddressInput = page.getByLabel(/shipping address/i);
    await expect(shippingAddressInput).toBeVisible();
    await shippingAddressInput.fill('123 Main St, Anytown, USA');

    // Step 4: Enter billing address
    const billingAddressInput = page.getByLabel(/billing address/i);
    await billingAddressInput.fill('456 Elm St, Anytown, USA');

    // Step 5: Select payment method
    const paymentMethodSelect = page.getByLabel(/payment method/i);
    await paymentMethodSelect.click();
    const creditCardButton = page.getByRole('button', { name: /credit card/i });
    await creditCardButton.click();

    // Step 6: Enter card details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111111');

    const expiryDateInput = page.getByLabel(/expiry date/i);
    await expiryDateInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    // Step 7: Review and confirm order
    const reviewButton = page.getByRole('button', { name: /review/i });
    await reviewButton.click();
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();
    await confirmButton.click();

    // Step 8: Verify success message
    const successMessage = page.getByText(/order confirmed/i);
    await expect(successMessage).toBeVisible();

    // Step 9: Verify order details
    const orderDetails = page.getByText(/order number: 12345/i);
    await expect(orderDetails).toBeVisible();

    // Step 10: Verify order summary
    const orderSummary = page.getByText(/order total: $100.00/i);
    await expect(orderSummary).toBeVisible();

    // Step 11: Verify order status
    const orderStatus = page.getByText(/order status: processing/i);
    await expect(orderStatus).toBeVisible();

    // Step 12: Verify order confirmation email
    const emailLink = page.getByRole('link', { name: /order confirmation/i });
    await expect(emailLink).toBeVisible();

    // Step 13: Verify order in cart
    const cartCount = page.getByText('Cart Items: 0');
    await expect(cartCount).toBeVisible();
  });

